for (let i = 0; i < 5; i++) {
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });
  const status = await browserjs(tabId, () => {
    const skipBtn = document.querySelector('.ytp-skip-ad-button, .ytp-ad-skip-button-modern, .ytp-ad-skip-button');
    if (skipBtn) skipBtn.click();
    const video = document.querySelector('video');
    const title = document.querySelector('h1.ytd-watch-metadata yt-formatted-string')?.textContent?.trim() || document.title;
    const isAd = !!document.querySelector('.ad-showing');
    const durationText = document.querySelector('.ytp-time-duration')?.textContent?.trim();
    const timeCurrent = document.querySelector('.ytp-time-current')?.textContent?.trim();
    return {
      title,
      isAd,
      durationText,
      timeCurrent,
      videoDurationSec: video ? video.duration : null,
      videoCurrentTime: video ? video.currentTime : null,
      paused: video ? video.paused : null
    };
  });
  console.log(`Check ${i + 1}:`, status);
  if (!status.isAd && status.videoDurationSec > 60) {
    console.log("Confirmed real video is playing!");
    break;
  }
}

